// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const H = new Float64Array( 9 );
	const V = new Float64Array( 3 );

	dlaqr1(); // $ExpectError
	dlaqr1( 'row-major' ); // $ExpectError
	dlaqr1( 'row-major', 3 ); // $ExpectError
	dlaqr1( 'row-major', 3, H ); // $ExpectError
	dlaqr1( 'row-major', 3, H, 3 ); // $ExpectError
	dlaqr1( 'row-major', 3, H, 3, 1.5 ); // $ExpectError
	dlaqr1( 'row-major', 3, H, 3, 1.5, 0.0 ); // $ExpectError
	dlaqr1( 'row-major', 3, H, 3, 1.5, 0.0, 2.5 ); // $ExpectError
	dlaqr1( 'row-major', 3, H, 3, 1.5, 0.0, 2.5, 0.0 ); // $ExpectError
	dlaqr1( 'row-major', 3, H, 3, 1.5, 0.0, 2.5, 0.0, V, 10 ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a Float64Array...
{
	const H = new Float64Array( 9 );
	const V = new Float64Array( 3 );

	dlaqr1.ndarray( 3, H, 3, 1, 0, 1.5, 0.0, 2.5, 0.0, V, 1, 0 ); // $ExpectType Float64Array
}

